/*
 FULLSEND Purple Dragon / Sakura — Gamepad Viewer Xbox V3
 Straight/front 2D rebuild.
*/
html,body{background:transparent!important;overflow:hidden!important;}
.controller.xbox.edit{width:750px!important;height:630px!important;background:url("data:image/png;base64,") 0 0/750px 630px no-repeat!important;}
.controller.xbox.edit.white,.controller.xbox.edit.disconnected{background:url("data:image/png;base64,") 0 0/750px 630px no-repeat!important;}
.xbox.edit .quadrant{display:none!important;}

/* STICKS */
.xbox.edit .sticks{position:absolute!important;width:750px!important;height:630px!important;left:0!important;top:0!important;z-index:30!important;pointer-events:none!important;}
.xbox.edit .stick{position:absolute!important;width:60px!important;height:60px!important;border-radius:50%!important;background-repeat:no-repeat!important;background-position:center!important;background-size:60px 60px!important;margin:0!important;}
.xbox.edit .stick.left{left:179.3px!important;top:233.6px!important;background-image:url("data:image/png;base64,")!important;}
.xbox.edit .stick.right{left:425.4px!important;top:330.3px!important;background-image:url("data:image/png;base64,")!important;background-color:transparent!important;}
.xbox.edit .stick.pressed{background-position:center!important;filter:brightness(1.14) drop-shadow(0 0 5px rgba(190,55,255,.75))!important;}

/* ABXY */
.xbox.edit .abxy{position:absolute!important;width:750px!important;height:630px!important;left:0!important;top:0!important;z-index:35!important;}
.xbox.edit .button{position:absolute!important;width:42px!important;height:42px!important;border-radius:50%!important;background-repeat:no-repeat!important;background-position:center!important;background-size:42px 42px!important;margin:0!important;}
.xbox.edit .button.a{left:524.1px!important;top:295.7px!important;background-image:url("data:image/png;base64,")!important;}
.xbox.edit .button.b{left:563.3px!important;top:255.4px!important;right:auto!important;background-image:url("data:image/png;base64,")!important;}
.xbox.edit .button.x{left:480.1px!important;top:254.9px!important;background-image:url("data:image/png;base64,")!important;}
.xbox.edit .button.y{left:523.6px!important;top:215.6px!important;background-image:url("data:image/png;base64,")!important;}
.xbox.edit .button.pressed{margin-top:0!important;background-position:center!important;filter:brightness(1.28) drop-shadow(0 0 5px rgba(215,105,255,.95)) drop-shadow(0 0 10px rgba(145,0,230,.70))!important;transform:scale(.96)!important;}

/* DPAD */
.xbox.edit .dpad{position:absolute!important;width:106px!important;height:106px!important;left:243.6px!important;top:318.6px!important;z-index:40!important;}
.xbox.edit .face{position:absolute!important;opacity:0!important;background-image:none!important;background-color:rgba(190,48,255,.67)!important;box-shadow:0 0 8px rgba(176,32,255,.65)!important;}
.xbox.edit .face.pressed{opacity:1!important;}
.xbox.edit .face.up{width:31px!important;height:48px!important;left:37.5px!important;top:3px!important;border-radius:7px 7px 2px 2px!important;}
.xbox.edit .face.down{width:31px!important;height:48px!important;left:37.5px!important;bottom:3px!important;border-radius:2px 2px 7px 7px!important;}
.xbox.edit .face.left{width:48px!important;height:31px!important;left:3px!important;top:37.5px!important;border-radius:7px 2px 2px 7px!important;}
.xbox.edit .face.right{width:48px!important;height:31px!important;right:3px!important;top:37.5px!important;border-radius:2px 7px 7px 2px!important;}

/* VIEW / MENU */
.xbox.edit .arrows{position:absolute!important;left:0!important;top:0!important;width:750px!important;height:630px!important;z-index:42!important;}
.xbox.edit .back,.xbox.edit .start{position:absolute!important;float:none!important;width:31px!important;height:31px!important;border-radius:50%!important;background-image:none!important;background:rgba(191,55,255,.18)!important;border:2px solid rgba(210,100,255,0)!important;box-shadow:none!important;opacity:0!important;}
.xbox.edit .back{left:316.1px!important;top:258.3px!important;}
.xbox.edit .start{left:407.1px!important;top:259.9px!important;}
.xbox.edit .back.pressed,.xbox.edit .start.pressed{opacity:1!important;border-color:rgba(220,120,255,.9)!important;box-shadow:0 0 8px rgba(180,30,255,.85)!important;}

/* LT / RT — analog trigger value controls opacity */
.xbox.edit .triggers{position:absolute!important;left:0!important;top:0!important;width:750px!important;height:145px!important;z-index:48!important;visibility:visible!important;}
.xbox.edit .trigger{position:absolute!important;float:none!important;width:70px!important;height:105px!important;background:url("data:image/png;base64,") center/70px 105px no-repeat!important;opacity:0;filter:drop-shadow(0 0 6px rgba(165,25,245,.45))!important;}
.xbox.edit .trigger.left{left:183px!important;top:26px!important;transform:none!important;}
.xbox.edit .trigger.right{left:497px!important;top:26px!important;right:auto!important;transform:rotateY(180deg)!important;}

/* LB / RB */
.xbox.edit .bumpers{position:absolute!important;left:0!important;top:0!important;width:750px!important;height:190px!important;z-index:47!important;visibility:visible!important;}
.xbox.edit .bumper{position:absolute!important;float:none!important;width:150px!important;height:54px!important;background:url("data:image/png;base64,") center/150px 54px no-repeat!important;opacity:0!important;filter:drop-shadow(0 0 6px rgba(165,25,245,.40))!important;}
.xbox.edit .bumper.left{left:137px!important;top:116px!important;transform:none!important;}
.xbox.edit .bumper.right{left:463px!important;top:116px!important;right:auto!important;transform:rotateY(180deg)!important;}
.xbox.edit .bumper.pressed{opacity:1!important;}

.controller.xbox.edit::before,.controller.xbox.edit::after{content:none!important;display:none!important;}
